INSERT INTO collections (id, slug, name, tagline, description, image, accent, sort_order) VALUES
(1, 'winter-edit', 'The Winter Edit', 'Sculpted outerwear for cold-weather cities', 'Double-faced wools, storm-proof cottons and shearling linings cut for long winters in Seoul, Berlin and New York.', 'https://images.pexels.com/photos/19099688/pexels-photo-19099688.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1200&h=1500', '#1c2430', 1),
(2, 'elevated-essentials', 'Elevated Essentials', 'The everyday layer, reconsidered', 'Grade-A cashmere, merino and long-staple cottons in a palette designed to be worn on repeat, season after season.', 'https://images.pexels.com/photos/30569741/pexels-photo-30569741.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1200&h=1500', '#3a3128', 2),
(3, 'footwear-atelier', 'The Footwear Atelier', 'Hand-finished in Porto', 'Vegetable-tanned leathers, Blake-stitched soles and cushioned footbeds built in a family-run atelier in northern Portugal.', 'https://images.pexels.com/photos/12628400/pexels-photo-12628400.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1200&h=1500', '#101215', 3),
(4, 'after-hours', 'After Hours', 'Evening silhouettes in liquid silk', 'Bias-cut slips and column dresses that travel well, pack smaller and hold their drape from dinner to last call.', 'https://images.pexels.com/photos/15272935/pexels-photo-15272935.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1200&h=1500', '#221a20', 4)
INSERT INTO products (id, slug, name, subtitle, description, story, category, gender, collection_slug, price_cents, compare_at_cents, colors, sizes, size_type, images, image_labels, story_images, story_image_labels, details, materials, care, rating, review_count, stock, badge, is_featured, is_new_arrival, is_best_seller, created_at) VALUES
(1, 'aurora-double-faced-wool-coat', 'Aurora Double-Faced Wool Coat', 'Unlined Italian wool, sculpted shoulder', 'A generously cut wrap coat in a double-faced wool from a mill in Biella.', 'Cut from a single 3.2 metre length of double-faced wool and finished by hand.', 'Outerwear', 'Women', 'winter-edit', 69000, 86000, '[{"hex":"#f8f6f2","name":"Optic White","family":"White"},{"hex":"#eae3d6","name":"Ivory","family":"White"},{"hex":"#121212","name":"Black","family":"Black"},{"hex":"#38393c","name":"Charcoal","family":"Black"}]', '["XS","S","M","L","XL"]', 'alpha', '["https://images.pexels.com/photos/29879990/pexels-photo-29879990.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/19099691/pexels-photo-19099691.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/19099688/pexels-photo-19099688.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/19169495/pexels-photo-19169495.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330"]', '["","","",""]', '[]', '[]', '["Relaxed fit — size down for a closer shape","Hidden press-stud placket with self-tie belt"]', '82% virgin wool, 18% cashmere.', 'Dry clean only.', 4.8, 4, 19, 'Atelier', TRUE, FALSE, FALSE, '2026-08-31T15:03:48.840Z'),
(2, 'meridian-cotton-trench', 'Meridian Cotton Trench', 'Storm-proof cotton gabardine', 'A modern trench with a cleaner shoulder and a longer line, cut in densely woven cotton gabardine that shrugs off a sudden downpour.', 'We rebuilt the classic trench block from scratch — dropping the belt loops, raising the collar stand and adding a two-way zip behind the placket so it works on a bike as well as in a taxi.', 'Outerwear', 'Women', 'winter-edit', 54000, NULL, '[{"hex":"#f8f6f2","name":"Optic White","family":"White"}]', '["XS","S","M","L","XL"]', 'alpha', '["https://images.pexels.com/photos/19099688/pexels-photo-19099688.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/19099691/pexels-photo-19099691.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/19138141/pexels-photo-19138141.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/9571461/pexels-photo-9571461.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330"]', '[]', '[]', '[]', '["Water-repellent finish, PFC-free","Two-way zip beneath a buttoned storm placket","Detachable self-belt with metal buckle","Back vent for movement"]', '100% cotton gabardine. Trim: recycled polyester twill.', 'Machine wash cold on a gentle cycle. Hang dry.', 4.5, 2, 25, NULL, FALSE, FALSE, FALSE, '2026-09-01T00:03:48.840Z'),
(3, 'halo-shearling-bomber', 'Halo Shearling Bomber', 'Recycled shearling, cropped line', 'A cropped bomber in plush recycled shearling with a wide shawl collar. Warm enough for -5°C, light enough to drive in.', 'The pile is knitted onto a recycled base rather than woven, which makes it stretchy, breathable and machine washable.', 'Outerwear', 'Women', 'winter-edit', 48000, 56000, '[{"hex":"#f8f6f2","name":"Optic White","family":"White"},{"hex":"#eae3d6","name":"Ivory","family":"White"},{"hex":"#121212","name":"Black","family":"Black"}]', '["XS","S","M","L","XL"]', 'alpha', '["https://images.pexels.com/photos/20264967/pexels-photo-20264967.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/35117783/pexels-photo-35117783.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/36185756/pexels-photo-36185756.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/19169491/pexels-photo-19169491.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330"]', '[]', '[]', '[]', '["Cropped at the high hip","Wide shawl collar and dropped shoulder","Recycled pile on a stretch knit base","Concealed side-entry pockets"]', '62% recycled polyester, 33% wool, 5% elastane.', 'Machine wash cold, reshape while damp, dry flat.', 4.5, 2, 15, 'New', FALSE, TRUE, FALSE, '2026-09-01T09:03:48.840Z'),
(4, 'atlas-wool-overcoat', 'Atlas Wool Overcoatxxxxxxxxx', 'Single-breasted, half-canvassed', 'A single-breasted overcoat in a melton wool blend with a half-canvassed chest and a clean, undarted front.', 'Cut slightly shorter than a traditional overcoat so it reads sharp under a tailoring jacket and easy over a hoodie.', 'Outerwear', 'Men', 'winter-edit', 72000, NULL, '[{"hex":"#6b6d72","name":"Graphite","family":"Grey"},{"hex":"#38393c","name":"Charcoal","family":"Black"},{"hex":"#121212","name":"Black","family":"Black"},{"hex":"#f8f6f2","name":"Optic White","family":"White"}]', '["S","M","L","XL","XXL"]', 'alpha', '["https://images.pexels.com/photos/28426899/pexels-photo-28426899.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/29259451/pexels-photo-29259451.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/21967304/pexels-photo-21967304.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/19801910/pexels-photo-19801910.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330"]', '["razim","full court","",""]', '["https://images.pexels.com/photos/28426899/pexels-photo-28426899.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/29259451/pexels-photo-29259451.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/21967304/pexels-photo-21967304.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330"]', '["","",""]', '["Half-canvassed chest with floating horsehair canvas","Horn-look buttons, working cuff buttons","Interior pocket sized for a phone and passport","Centre back vent, 108cm length in size M"]', '70% wool, 20% polyamide, 10% cashmere. Lining: cupro.', 'Dry clean only. Brush with a horsehair brush between wears.', 4.7, 3, 16, NULL, TRUE, TRUE, FALSE, '2026-09-01T18:03:48.841Z'),
(5, 'noir-technical-parka', 'Noir Technical Parka', '3-layer shell, fully taped seams', 'A matte three-layer parka with a storm hood, pit zips and a drawcord hem — built for sideways rain and long airport walks.', 'The face fabric is a recycled nylon ripstop with a solvent-free membrane, rated 20k/20k so it breathes on the climb.', 'Outerwear', 'Unisex', 'winter-edit', 64000, NULL, '[{"hex":"#121212","name":"Black","family":"Black"},{"hex":"#38393c","name":"Charcoal","family":"Black"},{"hex":"#6b6d72","name":"Graphite","family":"Grey"}]', '["S","M","L","XL","XXL"]', 'alpha', '["https://images.pexels.com/photos/19801910/pexels-photo-19801910.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/21967304/pexels-photo-21967304.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/29037366/pexels-photo-29037366.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/16845071/pexels-photo-16845071.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330"]', '[]', '[]', '[]', '["20,000mm waterproof / 20,000g breathability","Fully taped seams and water-resistant zips","Adjustable storm hood with a stiffened brim","Packs into its own left pocket"]', '100% recycled nylon ripstop with a PFC-free membrane.', 'Machine wash cold with technical detergent. Do not tumble dry.', 5, 2, 22, NULL, FALSE, TRUE, FALSE, '2026-09-02T03:03:48.841Z'),
(6, 'cloudsoft-cashmere-crew', 'Cloudsoft Cashmere Crew', 'Grade-A Mongolian cashmere, 4-ply', 'A four-ply cashmere crew with ribbed edges and a slightly relaxed body. The fibres are 36mm long, which is why it never itches.', 'Knitted in Inner Mongolia on vintage flat-bed machines at a low tension, then washed in soft water for 40 minutes to bloom the halo.', 'Knitwear', 'Women', 'elevated-essentials', 32000, 39500, '[{"hex":"#f8f6f2","name":"Optic White","family":"White"},{"hex":"#eae3d6","name":"Ivory","family":"White"},{"hex":"#38393c","name":"Charcoal","family":"Black"},{"hex":"#121212","name":"Black","family":"Black"}]', '["XS","S","M","L","XL"]', 'alpha', '["https://images.pexels.com/photos/6995886/pexels-photo-6995886.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/24740436/pexels-photo-24740436.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/29865096/pexels-photo-29865096.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/30569741/pexels-photo-30569741.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330"]', '[]', '[]', '[]', '["4-ply, 620gsm Grade-A cashmere","Fully fashioned shoulders — no bulky seams","Ribbed collar, cuffs and hem","Relaxed body, sleeves cut to the wrist bone"]', '100% Grade-A Mongolian cashmere.', 'Hand wash cool with cashmere shampoo. Dry flat away from heat.', 4.7, 3, 34, NULL, TRUE, FALSE, TRUE, '2026-09-02T12:03:48.841Z'),
(7, 'ribbed-merino-turtleneck', 'Ribbed Merino Turtleneck', 'Extra-fine 19.5 micron merino', 'A fine-gauge ribbed turtleneck that layers flat under tailoring but reads as a statement on its own.', 'Knitted in a 3x1 rib with a touch of elastane so the collar keeps standing after the tenth wear.', 'Knitwear', 'Women', 'elevated-essentials', 24500, NULL, '[{"hex":"#f8f6f2","name":"Optic White","family":"White"},{"hex":"#121212","name":"Black","family":"Black"},{"hex":"#222d42","name":"Navy","family":"Blue"}]', '["XS","S","M","L","XL"]', 'alpha', '["https://images.pexels.com/photos/6995884/pexels-photo-6995884.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/6995898/pexels-photo-6995898.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/6996083/pexels-photo-6996083.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/14641430/pexels-photo-14641430.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330"]', '[]', '[]', '[]', '["Extra-fine 19.5 micron merino, machine washable","Self-standing ribbed collar","Sleeveless-friendly cropped hip length","Fully reversible silhouette"]', '96% extra-fine merino wool, 4% elastane.', 'Machine wash wool cycle at 30°C. Dry flat.', 4.5, 2, 45, NULL, FALSE, FALSE, TRUE, '2026-09-02T21:03:48.841Z'),
(8, 'atelier-oversized-cardigan', 'Atelier Oversized Cardigan', 'Chunky cable front, drop shoulder', 'A generously oversized cardigan with deep patch pockets, meant to be worn open as a house coat or belt as outerwear.', 'The yarn is a wool-cotton blend spun in Tuscany, giving cable definition without the weight of pure lambswool.', 'Knitwear', 'Unisex', 'elevated-essentials', 28500, NULL, '[{"hex":"#f8f6f2","name":"Optic White","family":"White"},{"hex":"#eae3d6","name":"Ivory","family":"White"},{"hex":"#121212","name":"Black","family":"Black"},{"hex":"#4a5343","name":"Moss","family":"Green"}]', '["S","M","L"]', 'alpha', '["https://images.pexels.com/photos/9603626/pexels-photo-9603626.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/29865096/pexels-photo-29865096.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/14641430/pexels-photo-14641430.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/24740436/pexels-photo-24740436.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330"]', '[]', '[]', '[]', '["Oversized — take your usual size for a relaxed fit","Deep patch pockets and dropped shoulders","Corozo nut buttons","Cable-front panel with plain sleeves"]', '55% wool, 40% cotton, 5% alpaca.', 'Hand wash cool or dry clean. Dry flat.', 5, 2, 27, NULL, FALSE, FALSE, FALSE, '2026-09-03T06:03:48.841Z'),
(9, 'heritage-cable-knit', 'Heritage Cable Knit', 'Lambswool fisherman knit', 'A traditional fisherman''s cable knit with saddle shoulders and a high neck, updated with a slightly slimmer sleeve.', 'Knitted in a Scottish mill that has been making ganseys since 1874, using lambswool from the Borders.', 'Knitwear', 'Men', 'elevated-essentials', 26500, NULL, '[{"hex":"#f8f6f2","name":"Optic White","family":"White"},{"hex":"#38393c","name":"Charcoal","family":"Black"},{"hex":"#1f2942","name":"Navy","family":"Blue"}]', '["S","M","L","XL","XXL"]', 'alpha', '["https://images.pexels.com/photos/12056642/pexels-photo-12056642.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/30569741/pexels-photo-30569741.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/14641430/pexels-photo-14641430.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/9603626/pexels-photo-9603626.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330"]', '[]', '[]', '[]', '["Saddle shoulder for a fuller chest","Traditional honeycomb and cable panels","Ribbed funnel neck","Naturally water-resistant lanolin-rich wool"]', '100% British lambswool.', 'Hand wash cool. Dry flat. Refresh in fresh air between wears.', 4.5, 2, 23, NULL, FALSE, FALSE, FALSE, '2026-09-03T15:03:48.841Z'),
(10, 'nova-court-leather-sneaker', 'Nova Court Leather Sneaker', 'Italian calfskin, cupsole', 'A pared-back court sneaker in full-grain Italian calfskin on a hand-stitched cupsole. No logos, no branding — just the shape.', 'The upper is cut from a single hide so the grain runs continuously down the vamp, then Blake-stitched to the sole so it can be resoled.', 'Footwear', 'Unisex', 'footwear-atelier', 24000, NULL, '[{"hex":"#f8f6f2","name":"Optic White","family":"White"},{"hex":"#eae3d6","name":"Ivory","family":"White"},{"hex":"#121212","name":"Black","family":"Black"}]', '["40","41","42","43","44","45"]', 'shoe', '["https://images.pexels.com/photos/7193629/pexels-photo-7193629.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/18202585/pexels-photo-18202585.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/7193625/pexels-photo-7193625.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/12628400/pexels-photo-12628400.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330"]', '[]', '[]', '[]', '["Full-grain calfskin from a Tuscan tannery","Blake-stitched, fully resoleable cupsole","Removable moulded footbed with arch support","Runs true to size; half sizes coming soon"]', 'Upper: Italian calfskin. Lining: vegetable-tanned leather. Sole: natural rubber.', 'Wipe with a damp cloth. Condition every 8-10 wears.', 4.7, 3, 40, NULL, TRUE, FALSE, TRUE, '2026-09-04T00:03:48.841Z'),
(11, 'trace-runner', 'Trace Runner', 'Recycled knit upper, foam midsole', 'A low-profile everyday runner in a seamless recycled knit with a supercritical foam midsole and a 6mm drop.', 'Weighs 218g in a size 42. The midsole foam is nitrogen-injected, so it stays lively past 600km.', 'Footwear', 'Unisex', 'footwear-atelier', 21000, 25000, '[{"hex":"#f8f6f2","name":"Optic White","family":"White"},{"hex":"#6b6d72","name":"Graphite","family":"Grey"},{"hex":"#121212","name":"Black","family":"Black"}]', '["40","41","42","43","44","45"]', 'shoe', '["https://images.pexels.com/photos/8188879/pexels-photo-8188879.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/20191568/pexels-photo-20191568.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/20191567/pexels-photo-20191567.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/18202585/pexels-photo-18202585.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330"]', '[]', '[]', '[]', '["218g (size 42)","6mm heel-to-toe drop","Seamless recycled knit upper — no tongue break","Nitrogen-injected supercritical foam"]', 'Upper: 92% recycled polyester knit. Midsole: EVA/TPU blend. Outsole: recycled rubber.', 'Hand wash upper with mild soap. Air dry.', 5, 2, 51, NULL, FALSE, FALSE, TRUE, '2026-09-04T09:03:48.841Z'),
(12, 'pop-court-sneaker', 'Pop Court Sneakercccccccccccccccccc', 'Colour-blocked suede and mesh', 'The Court''s louder sibling: colour-blocked suede overlays on a breathable mesh base with a gum rubber outsole.', 'Developed with a small studio in Porto that specialises in hand-burnished suede panels.', 'Footwear', 'Unisex', 'footwear-atelier', 19500, NULL, '[{"hex":"#2b4c9b","name":"Cobalt","family":"Blue"},{"hex":"#b8342c","name":"Signal Red","family":"Red"},{"hex":"#f6f4f0","name":"Optic White","family":"White"}]', '["40","41","42","43","44","45"]', 'shoe', '["https://images.pexels.com/photos/11324546/pexels-photo-11324546.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/11324526/pexels-photo-11324526.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/14525666/pexels-photo-14525666.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/20191567/pexels-photo-20191567.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330"]', '[]', '[]', '[]', '["Hand-burnished suede overlays","Gum rubber outsole with a herringbone tread","Padded collar and cushioned insole","Sizing: generous — consider going down a half size"]', 'Upper: pig suede and recycled mesh. Outsole: natural gum rubber.', 'Brush suede dry. Protect with a suede spray before first wear.', 4.5, 2, 108, 'Limited', TRUE, TRUE, FALSE, '2026-09-04T18:03:48.841Z'),
(13, 'meridian-chelsea-boot', 'Meridian Chelsea Boot', 'Vegetable-tanned leather, chunky sole', 'A city Chelsea boot in vegetable-tanned leather with elasticated gussets and a lug sole that actually grips on wet stone.', 'The last is based on a 1960s Italian motoring boot — narrow at the waist, generous at the toe.', 'Footwear', 'Women', 'footwear-atelier', 42000, NULL, '[{"hex":"#121212","name":"Black","family":"Black"},{"hex":"#38393c","name":"Charcoal","family":"Black"},{"hex":"#6b6d72","name":"Graphite","family":"Grey"}]', '["36","37","38","39","40","41"]', 'shoe', '["https://images.pexels.com/photos/18911766/pexels-photo-18911766.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/12586098/pexels-photo-12586098.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/34235456/pexels-photo-34235456.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/11332376/pexels-photo-11332376.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330"]', '[]', '[]', '[]', '["Vegetable-tanned leather, 1.8mm thickness","Blake-stitched with a storm welt","Dual-density rubber lug sole, 25mm","Leather-lined with a padded footbed"]', 'Upper and lining: vegetable-tanned Italian leather. Sole: rubber/cork composite.', 'Condition monthly. Use a cedar shoe tree between wears.', 4.7, 3, 22, NULL, TRUE, FALSE, FALSE, '2026-09-05T03:03:48.841Z'),
(14, 'solstice-knee-boot', 'Solstice Knee Boot', 'Stretch leather, sculpted heel', 'A knee-high boot in a stretch leather that hugs the calf without a zip, set on a sculpted 60mm block heel.', 'The stretch comes from a bonded knit back, not from thin leather, so it keeps its shape all day.', 'Footwear', 'Women', 'footwear-atelier', 52000, NULL, '[{"hex":"#121212","name":"Black","family":"Black"},{"hex":"#38393c","name":"Charcoal","family":"Black"}]', '["36","37","38","39","40","41"]', 'shoe', '["https://images.pexels.com/photos/32366927/pexels-photo-32366927.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/7062176/pexels-photo-7062176.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/19120507/pexels-photo-19120507.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/10910252/pexels-photo-10910252.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330"]', '[]', '[]', '[]', '["Zip-free pull-on construction","60mm sculpted block heel","Circumference 36cm at the top (size 38)","Softly squared almond toe"]', 'Upper: stretch lambskin on a knit back. Sole: leather with a rubber toplift.', 'Wipe clean. Store upright with boot shapers.', 5, 2, 13, 'Runway', TRUE, FALSE, FALSE, '2026-09-05T12:03:48.841Z'),
(15, 'terrace-leather-loafer', 'Terrace Leather Loafer', 'Hand-sewn apron, flexible sole', 'An unlined apron-toe loafer that''s built to be worn without socks and thrown in a bag for travel.', 'The apron is sewn by hand with a saddle stitch, which is why it moulds to your foot within a week.', 'Footwear', 'Unisex', 'footwear-atelier', 31000, NULL, '[{"hex":"#f8f6f2","name":"Optic White","family":"White"},{"hex":"#121212","name":"Black","family":"Black"},{"hex":"#6b6d72","name":"Graphite","family":"Grey"}]', '["40","41","42","43","44","45"]', 'shoe', '["https://images.pexels.com/photos/11332376/pexels-photo-11332376.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/12586098/pexels-photo-12586098.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/34235456/pexels-photo-34235456.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/8411014/pexels-photo-8411014.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330"]', '[]', '[]', '[]', '["Hand-sewn apron with a saddle stitch","Unlined for a barefoot feel","Flexible rubber-city sole","Sizing: runs large — size down half"]', 'Upper: vegetable-tanned calf. Sole: flexible rubber.', 'Wipe with a damp cloth. Cream polish occasionally.', 4.5, 2, 28, NULL, FALSE, FALSE, FALSE, '2026-09-05T21:03:48.841Z'),
(16, 'liquid-silk-slip-dress', 'Liquid Silk Slip Dress', '22-momme bias-cut mulberry silk', 'A bias-cut slip in heavyweight 22-momme mulberry silk that skims rather than clings, with adjustable straps.', 'Cut on the true bias from a single panel so the dress spirals around the body — there are only two seams.', 'Dresses', 'Women', 'after-hours', 38000, 45000, '[{"hex":"#121212","name":"Black","family":"Black"},{"hex":"#eae3d6","name":"Ivory","family":"White"},{"hex":"#5d1f2b","name":"Bordeaux","family":"Red"}]', '["XS","S","M","L","XL"]', 'alpha', '["https://images.pexels.com/photos/15272935/pexels-photo-15272935.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/20821761/pexels-photo-20821761.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/5822538/pexels-photo-5822538.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/17541235/pexels-photo-17541235.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330"]', '[]', '[]', '[]', '["22-momme mulberry silk, matte finish","True bias cut with French seams","Adjustable sliders on the straps","Midi length, 118cm centre back"]', '100% mulberry silk, OEKO-TEX certified.', 'Dry clean recommended, or hand wash cold with silk detergent.', 4.7, 3, 20, NULL, TRUE, FALSE, TRUE, '2026-09-06T06:03:48.841Z'),
(17, 'sunlight-linen-shirt-dress', 'Sunlight Linen Shirt Dress', 'Washed European linen', 'A shirt dress in garment-washed European linen with a detachable belt and a deep back pleat for movement.', 'The linen is woven in Normandy and washed three times before cutting, so it arrives already soft.', 'Dresses', 'Women', 'elevated-essentials', 26500, NULL, '[{"hex":"#f8f6f2","name":"Optic White","family":"White"},{"hex":"#eae3d6","name":"Ivory","family":"White"},{"hex":"#a7bcd0","name":"Sky","family":"Blue"}]', '["XS","S","M","L","XL"]', 'alpha', '["https://images.pexels.com/photos/20117711/pexels-photo-20117711.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/37291294/pexels-photo-37291294.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/12466607/pexels-photo-12466607.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/34891485/pexels-photo-34891485.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330"]', '[]', '[]', '[]', '["Garment-washed Normandy linen, 190gsm","Detachable self-belt","Deep back box pleat","Mother-of-pearl buttons"]', '100% European flax linen.', 'Machine wash cold. Tumble dry low to soften.', 4.5, 2, 31, NULL, FALSE, TRUE, FALSE, '2026-09-06T15:03:48.841Z'),
(18, 'ivory-column-dress', 'Ivory Column Dress', 'Crepe column, open back', 'A floor-sweeping column in heavy crepe with a square neckline and an open, cowl-hung back.', 'Internally boned through the bodice so it holds its line without a bra, and hemmed by hand.', 'Dresses', 'Women', 'after-hours', 62000, NULL, '[{"hex":"#f2ece1","name":"Ivory","family":"White"},{"hex":"#161a28","name":"Midnight","family":"Blue"}]', '["XS","S","M","L","XL"]', 'alpha', '["https://images.pexels.com/photos/28442112/pexels-photo-28442112.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/34891485/pexels-photo-34891485.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/34896846/pexels-photo-34896846.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/5822538/pexels-photo-5822538.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330"]', '[]', '[]', '[]', '["Internally boned bodice with a shelf bra","Square front neckline, cowl back","Heavy stretch crepe, 320gsm","Floor length, hand-finished hem"]', '78% triacetate, 22% polyester crepe.', 'Dry clean only. Steam to release creases.', 5, 2, 11, NULL, FALSE, FALSE, FALSE, '2026-09-07T00:03:48.841Z'),
(19, 'rose-satin-gown', 'Rose Satin Gown', 'Draped cowl, floor length', 'A liquid satin gown with a softly draped cowl front and a low, gathered back. Made for photographs.', 'The satin is a heavy 40d trilobal that reflects light in a soft halo rather than a hard shine.', 'Dresses', 'Women', 'after-hours', 54000, NULL, '[{"hex":"#d9a2a4","name":"Rose","family":"Pink"},{"hex":"#131114","name":"Black","family":"Black"}]', '["XS","S","M","L","XL"]', 'alpha', '["https://images.pexels.com/photos/34896846/pexels-photo-34896846.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/5822538/pexels-photo-5822538.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/34891485/pexels-photo-34891485.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/28442112/pexels-photo-28442112.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330"]', '[]', '[]', '[]', '["Draped cowl front and back","Hidden side zip with a hook-and-eye","Floor length with a slight train","Cut on the bias through the skirt"]', '100% trilobal polyester satin with a matte crepe back.', 'Dry clean only. Store hanging.', 4, 3, 14, NULL, FALSE, TRUE, FALSE, '2026-09-07T09:03:48.841Z'),
(20, 'sculpt-wool-blazer', 'Sculpt Wool Blazer', 'Half-canvassed, sharp shoulder', 'A single-breasted blazer with a lightly padded shoulder, nipped waist and a length that hits at the high hip.', 'The shoulder is built with a thin wadding layer rather than a rope, so it reads strong but not 80s.', 'Tailoring', 'Women', 'elevated-essentials', 48000, NULL, '[{"hex":"#f8f6f2","name":"Optic White","family":"White"},{"hex":"#121212","name":"Black","family":"Black"},{"hex":"#38393c","name":"Charcoal","family":"Black"},{"hex":"#22352c","name":"Bottle","family":"Green"}]', '["XS","S","M","L","XL"]', 'alpha', '["https://images.pexels.com/photos/27869836/pexels-photo-27869836.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/39202946/pexels-photo-39202946.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/15127334/pexels-photo-15127334.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/19222080/pexels-photo-19222080.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330"]', '[]', '[]', '[]', '["Half-canvassed with a floating chest canvas","Lightly padded shoulder, two-button front","Functional cuff buttons","Bemberg cupro lining"]', '96% wool, 4% elastane suiting. Lining: cupro.', 'Dry clean only. Press on a tailor''s ham.', 5, 2, 24, NULL, TRUE, FALSE, FALSE, '2026-09-07T18:03:48.841Z'),
(21, 'wide-leg-pleated-trouser', 'Wide-Leg Pleated Trouser', 'Fluid drape, high rise', 'A high-rise, double-pleated trouser in a fluid wool blend that falls straight from the hip to a full break.', 'We tested eleven drafts before landing on a leg that reads wide but doesn''t swamp a smaller frame.', 'Tailoring', 'Women', 'elevated-essentials', 26000, NULL, '[{"hex":"#121212","name":"Black","family":"Black"},{"hex":"#f8f6f2","name":"Optic White","family":"White"},{"hex":"#212b40","name":"Navy","family":"Blue"}]', '["XS","S","M","L","XL"]', 'alpha', '["https://images.pexels.com/photos/22223037/pexels-photo-22223037.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/27869836/pexels-photo-27869836.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/8891480/pexels-photo-8891480.png?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/39202946/pexels-photo-39202946.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330"]', '[]', '[]', '[]', '["High rise with a hidden hook closure","Double front pleats","Full-length wide leg, 30cm opening","Unhemmed — free tailoring in-store"]', '68% wool, 30% viscose, 2% elastane.', 'Dry clean. Steam the pleats back in after travel.', 4.5, 2, 35, NULL, FALSE, FALSE, TRUE, '2026-09-08T03:03:48.841Z'),
(22, 'essential-pima-tee', 'Essential Pima Tee', 'Long-staple Peruvian pima', 'A mid-weight tee in long-staple Peruvian pima with a clean bound neckline that won''t stretch out.', 'Knitted at 200gsm, so it''s opaque enough to wear alone and smooth enough to layer under tailoring.', 'Essentials', 'Unisex', 'elevated-essentials', 8500, NULL, '[{"hex":"#f8f6f2","name":"Optic White","family":"White"},{"hex":"#eae3d6","name":"Ivory","family":"White"},{"hex":"#121212","name":"Black","family":"Black"},{"hex":"#a9b3a0","name":"Sage","family":"Green"}]', '["S","M","L","XL","XXL"]', 'alpha', '["https://images.pexels.com/photos/18516744/pexels-photo-18516744.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/18516754/pexels-photo-18516754.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/19771909/pexels-photo-19771909.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/19222080/pexels-photo-19222080.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330"]', '[]', '[]', '[]', '["200gsm long-staple Peruvian pima","Bound neckline, twin-needle hems","Pre-shrunk and bio-washed","Boxy but not cropped"]', '100% Peruvian pima cotton.', 'Machine wash cold. Tumble dry low.', 4.7, 3, 96, NULL, FALSE, FALSE, TRUE, '2026-09-08T12:03:48.841Z'),
(23, 'noir-evening-dress', 'Noir Evening Dress', 'Structured bodice, draped skirt', 'A black evening dress with a structured strapless bodice and a softly draped skirt that catches light as you move.', 'The bodice is bonded rather than boned, giving structure without any rigidity at the ribcage.', 'Dresses', 'Women', 'after-hours', 56000, NULL, '[{"hex":"#121212","name":"Black","family":"Black"},{"hex":"#38393c","name":"Charcoal","family":"Black"}]', '["XS","S","M","L","XL"]', 'alpha', '["https://images.pexels.com/photos/29977336/pexels-photo-29977336.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/17541235/pexels-photo-17541235.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/20821761/pexels-photo-20821761.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/19771909/pexels-photo-19771909.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330"]', '[]', '[]', '[]', '["Bonded structured bodice","Strapless with a silicone grip line","Draped skirt with a concealed side zip","Midi length with an asymmetric hem"]', '92% recycled polyester crepe, 8% elastane.', 'Dry clean only.', 5, 2, 10, NULL, FALSE, FALSE, FALSE, '2026-09-08T21:03:48.841Z'),
(24, 'atlas-denim-jacket', 'Atlas Denim Jacket', 'Selvedge denim, Kyoto loom', 'A boxy denim jacket in 13oz selvedge denim woven on shuttle looms in Okayama, cut to layer over knitwear.', 'Unwashed and rigid at first, it fades to your body within three months of daily wear.', 'Outerwear', 'Unisex', 'elevated-essentials', 29000, NULL, '[{"hex":"#26364f","name":"Rinse Indigo","family":"Blue"},{"hex":"#232326","name":"Washed Black","family":"Black"}]', '["S","M","L","XL","XXL"]', 'alpha', '["https://images.pexels.com/photos/15299304/pexels-photo-15299304.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/29197620/pexels-photo-29197620.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/21967310/pexels-photo-21967310.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330","https://images.pexels.com/photos/19338688/pexels-photo-19338688.png?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330"]', '[]', '[]', '[]', '["13oz unsanforized selvedge denim from Okayama","Boxy cut with a slightly longer body","Copper rivets and a chain-stitched hem","Rigid — expect 2cm shrink on first wash"]', '100% cotton selvedge denim.', 'Wash rarely, cold, inside out. Hang dry in the shade.', 4.5, 2, 29, NULL, FALSE, FALSE, FALSE, '2026-09-09T06:03:48.841Z'),
(36, 'navidu', 'navidu', 'ccccccccccccccc', 'afafssfsdf', 'ssssssssssssssssssssssssssssssssssssssssssssssssss', 'Essentials', 'Unisex', 'winter-edit', 80000, 30000, '[{"hex":"#f8f6f2","name":"Optic White","family":"White"},{"hex":"#121212","name":"Black","family":"Black"},{"hex":"#eae3d6","name":"Ivory","family":"White"}]', '["S","M","L","XL","XXL"]', 'alpha', '["https://images.pexels.com/photos/30569741/pexels-photo-30569741.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330"]', '[]', '[]', '[]', '[]', '', '', 5, 0, 17, 'Limited', FALSE, TRUE, FALSE, '2026-09-09T17:22:13.921Z'),
(37, 'sasika', 'sasika', 'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx', 'xsafsafassa', 'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx', 'Footwear', 'Unisex', 'winter-edit', 80000, 20000, '[{"hex":"#f8f6f2","name":"Optic White","family":"White"},{"hex":"#121212","name":"Black","family":"Black"},{"hex":"#222d42","name":"Navy","family":"Blue"},{"hex":"#6b6d72","name":"Graphite","family":"Grey"}]', '["S","M","L","XL","XXL"]', 'alpha', '["https://images.pexels.com/photos/30569741/pexels-photo-30569741.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=1000&h=1330"]', '[]', '[]', '[]', '[]', '', '', 5, 0, 32, 'Limited', TRUE, FALSE, FALSE, '2026-09-09T17:24:59.039Z'),
(39, 'nike-shoe', 'nike shoe', 'unbiliverbal', 'zzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzz', '', 'Footwear', 'Women', 'winter-edit', 800000, 200000, '[{"hex":"#f8f6f2","name":"Optic White","family":"White"},{"hex":"#121212","name":"Black","family":"Black"},{"hex":"#222d42","name":"Navy","family":"Blue"},{"hex":"#eae3d6","name":"Ivory","family":"White"}]', '["S","M","L","XXL","XL","XS"]', 'alpha', '["https://unsplash.com/photos/sunflower-field-during-day-time-lk3F07BN8T8"]', '[]', '[]', '[]', '[]', '', '', 5, 0, 32, 'Limited', TRUE, FALSE, FALSE, '2026-09-09T17:34:39.594Z')
