INSERT INTO reviews (id, product_id, customer_id, author, location, rating, title, body, verified, created_at) VALUES
(1, 1, NULL, 'Maren K.', 'Copenhagen, DK', 5, 'Worth every krone', 'The wool is dense but somehow weightless. I''ve worn it through a Danish February with only a cashmere crew underneath.', TRUE, '2026-08-11T15:03:48.851Z'),
(2, 1, NULL, 'Priya S.', 'Toronto, CA', 5, 'The drape is unreal', 'It falls exactly like the photos. Ordered the Ivory and it has not pilled once after two months of daily wear.', TRUE, '2026-07-15T15:03:48.851Z'),
(3, 1, NULL, 'Yuki T.', 'Tokyo, JP', 4, 'Beautiful, slightly long', 'Gorgeous coat. I''m 163cm so I had the hem taken up 4cm — the tailor commented on the quality of the wool.', TRUE, '2026-05-21T15:03:48.851Z'),
(4, 2, NULL, 'Elodie B.', 'Lyon, FR', 5, 'Rain tested', 'Walked 25 minutes in proper rain and stayed completely dry. It dries in an hour and doesn''t wrinkle.', TRUE, '2026-09-06T15:03:48.851Z'),
(5, 2, NULL, 'Hana A.', 'Dubai, AE', 4, 'Great for travel', 'Packs down small and the Graphite is a beautiful deep shade in person. Runs a touch large in the shoulders.', TRUE, '2026-08-18T15:03:48.851Z'),
(6, 3, NULL, 'Sofia R.', 'Milan, IT', 5, 'So soft it feels illegal', 'The pile is genuinely cloud-like and it hasn''t shed on black tops at all.', TRUE, '2026-08-20T15:03:48.851Z'),
(7, 3, NULL, 'Nadia F.', 'Istanbul, TR', 4, 'Warm and light', 'Surprised how warm it is for the weight. I would size up if you want to layer a knit under it.', TRUE, '2026-09-01T15:03:48.851Z'),
(8, 4, NULL, 'Daniel O.', 'Chicago, US', 5, 'Beats coats at twice the price', 'The chest has real structure to it — it holds the shoulder line when you sit. Fit is true to size over a shirt.', TRUE, '2026-07-30T15:03:48.851Z'),
(9, 4, NULL, 'Ken W.', 'Singapore, SG', 5, 'Tropical winter travel', 'Bought it for Tokyo in January. Warm, and the Graphite doesn''t show rain marks.', TRUE, '2026-08-16T15:03:48.851Z'),
(10, 4, NULL, 'Anders L.', 'Oslo, NO', 4, 'Lovely, sleeves run long', 'Had the sleeves shortened 2cm. Otherwise the best coat I''ve owned.', TRUE, '2026-06-14T15:03:48.851Z'),
(11, 5, NULL, 'Tom H.', 'Manchester, UK', 5, 'Manchester approved', 'If it survives a Mancunian winter it survives anything. Genuinely waterproof.', TRUE, '2026-08-16T15:03:48.851Z'),
(12, 5, NULL, 'Ines M.', 'Lisbon, PT', 5, 'Slick and quiet', 'Not crinkly like most shells. The Black is a proper deep matte.', TRUE, '2026-07-05T15:03:48.851Z'),
(13, 6, NULL, 'Claire D.', 'Melbourne, AU', 5, 'Third one', 'I now own this in three colours. Two winters in, the first one still looks new.', TRUE, '2026-08-04T15:03:48.851Z'),
(14, 6, NULL, 'Anita V.', 'Berlin, DE', 5, 'Not itchy at all', 'I have very reactive skin and this is the only cashmere I can wear against bare skin.', TRUE, '2026-08-22T15:03:48.851Z'),
(15, 6, NULL, 'Lucia P.', 'Buenos Aires, AR', 4, 'Size up for slouch', 'True to size, but I like it oversized so I went up one and it''s perfect.', TRUE, '2026-05-30T15:03:48.851Z'),
(16, 7, NULL, 'Rosa M.', 'Madrid, ES', 5, 'The perfect base layer', 'Disappears under a blazer and the collar doesn''t slouch. I''m on my second.', TRUE, '2026-08-07T15:03:48.851Z'),
(17, 7, NULL, 'Julia N.', 'Warsaw, PL', 4, 'Great, slightly sheer', 'In Optic White it needs a skin-tone bra. Navy is fully opaque.', TRUE, '2026-07-29T15:03:48.851Z'),
(18, 8, NULL, 'Freya L.', 'Reykjavik, IS', 5, 'My whole winter', 'Enormous, cosy and the Ivory colour is beautiful. Wears like a coat indoors.', TRUE, '2026-08-15T15:03:48.851Z'),
(19, 8, NULL, 'Mark J.', 'Portland, US', 5, 'Bought the Moss', 'Great neutral green, not too bright. Buttons feel solid.', TRUE, '2026-08-20T15:03:48.851Z'),
(20, 9, NULL, 'Callum R.', 'Edinburgh, UK', 5, 'Proper jumper', 'Heavy, warm and the lanolin smell is oddly nostalgic. Exactly what I hoped for.', TRUE, '2026-08-30T15:03:48.851Z'),
(21, 9, NULL, 'Theo K.', 'Vancouver, CA', 4, 'Chunky', 'Very substantial knit — a real winter piece rather than a layering one.', TRUE, '2026-07-15T15:03:48.851Z'),
(22, 10, NULL, 'Wei C.', 'Taipei, TW', 5, 'Zero break-in', 'Wore them for a 12-hour travel day straight out of the box. No blisters, no heel slip.', TRUE, '2026-08-25T15:03:48.851Z'),
(23, 10, NULL, 'Sasha G.', 'Brooklyn, US', 5, 'The white sneaker, done right', 'Clean toe box, no branding, and the leather has started to patina beautifully.', TRUE, '2026-06-29T15:03:48.851Z'),
(24, 10, NULL, 'Omar D.', 'Casablanca, MA', 4, 'Narrow-ish', 'Slightly narrow through the midfoot. Fine for me, but wide-footed friends should size up.', TRUE, '2026-07-14T15:03:48.851Z'),
(25, 11, NULL, 'Lena S.', 'Amsterdam, NL', 5, 'City miles', 'Bouncy but stable. I''ve done 300km including cobblestones and the foam still feels new.', TRUE, '2026-08-25T15:03:48.851Z'),
(26, 11, NULL, 'Ravi P.', 'Bengaluru, IN', 5, 'Breathes in 32°C', 'The knit is genuinely airy. No hot spots.', TRUE, '2026-09-01T15:03:48.851Z'),
(27, 12, NULL, 'Nina B.', 'Seoul, KR', 5, 'Photos don''t do the colour', 'The Cobalt is electric in person. Got stopped twice on the first day.', TRUE, '2026-08-08T15:03:48.851Z'),
(28, 12, NULL, 'Jonas E.', 'Hamburg, DE', 4, 'Fun shoe', 'Comfortable straight away. Suede marks easily, so treat it.', TRUE, '2026-07-01T15:03:48.851Z'),
(29, 13, NULL, 'Amélie R.', 'Paris, FR', 5, 'Paris-proof', 'Survived a week of rain on paving stones with zero slipping. The leather is thick and gorgeous.', TRUE, '2026-08-22T15:03:48.851Z'),
(30, 13, NULL, 'Grace T.', 'Sydney, AU', 5, 'Elegant and tough', 'Rare to find a lug sole that doesn''t look clunky. These read sleek under trousers.', TRUE, '2026-08-10T15:03:48.851Z'),
(31, 13, NULL, 'Mira H.', 'Stockholm, SE', 4, 'Stiff at first', 'Three wears to break in, then excellent. Order your usual size.', TRUE, '2026-06-20T15:03:48.851Z'),
(32, 14, NULL, 'Bianca F.', 'New York, US', 5, 'No zip, no gaping', 'They actually stay up on my calves, which never happens. Wore them for 10 hours at a trade show.', TRUE, '2026-07-31T15:03:48.851Z'),
(33, 14, NULL, 'Aiko M.', 'Osaka, JP', 5, 'Sculptural', 'The heel is a work of art. Comfortable for a 60mm boot.', TRUE, '2026-07-07T15:03:48.851Z'),
(34, 15, NULL, 'Léa C.', 'Geneva, CH', 5, 'Moulds to your foot', 'Unlined leather sounds odd but after a week it felt custom-made.', TRUE, '2026-08-04T15:03:48.851Z'),
(35, 15, NULL, 'Peter V.', 'Auckland, NZ', 4, 'Great, size down', 'Definitely half a size large. The Optic White is crisp and clean.', TRUE, '2026-08-08T15:03:48.851Z'),
(36, 16, NULL, 'Stella M.', 'Los Angeles, US', 5, 'Actually opaque', 'The 22-momme weight makes all the difference — no underwear show-through, and it doesn''t crease like cheaper silk.', TRUE, '2026-08-21T15:03:48.851Z'),
(37, 16, NULL, 'Farah K.', 'Doha, QA', 5, 'Wedding guest winner', 'Wore the Bordeaux to a wedding, packed it in a carry-on and it came out without a crease.', TRUE, '2026-06-17T15:03:48.851Z'),
(38, 16, NULL, 'Ivy L.', 'London, UK', 4, 'Long on petite frames', 'Gorgeous, but I''m 5''3" and it''s ankle length. Had it shortened 6cm.', TRUE, '2026-07-02T15:03:48.851Z'),
(39, 17, NULL, 'Marta G.', 'Barcelona, ES', 5, 'Summer uniform', 'Lives in my suitcase from May to September. Breathes beautifully at 35°C.', TRUE, '2026-08-24T15:03:48.851Z'),
(40, 17, NULL, 'Ellie W.', 'Cape Town, ZA', 4, 'Lovely, creases', 'It''s linen, so it creases — but that''s the look. The Optic White is beautifully crisp.', TRUE, '2026-06-23T15:03:48.851Z'),
(41, 18, NULL, 'Chloe A.', 'Sydney, AU', 5, 'Wore it to a gala', 'Three people asked who made it. The internal boning means no bra, no fuss.', TRUE, '2026-08-26T15:03:48.851Z'),
(42, 18, NULL, 'Noor S.', 'Amman, JO', 5, 'Sculpted', 'The crepe holds you in without being tight. True to size.', TRUE, '2026-07-31T15:03:48.851Z'),
(43, 19, NULL, 'Zoe H.', 'Austin, US', 5, 'The Rose colour', 'Somewhere between blush and mauve — far more sophisticated than the photos suggest.', TRUE, '2026-08-25T15:03:48.851Z'),
(44, 19, NULL, 'Isabel R.', 'Mexico City, MX', 4, 'Needs heels', 'Very long, so plan on heels or a hem. Beautiful drape.', TRUE, '2026-07-05T15:03:48.851Z'),
(45, 20, NULL, 'Helen Z.', 'Singapore, SG', 5, 'Office to dinner', 'The waist is properly nipped so it doesn''t look boxy over a dress. Excellent in humid weather.', TRUE, '2026-08-25T15:03:48.851Z'),
(46, 20, NULL, 'Dana Q.', 'Dublin, IE', 5, 'Best tailoring I own', 'The shoulder line is perfect. I''ve had it taken in slightly at the waist for a made-to-measure feel.', TRUE, '2026-06-17T15:03:48.851Z'),
(47, 21, NULL, 'Tara N.', 'Toronto, CA', 5, 'Finally, a wide leg that works', 'I''m 5''2" and these don''t drown me with a 3cm heel. The drape is beautiful.', TRUE, '2026-08-02T15:03:48.851Z'),
(48, 21, NULL, 'Sara K.', 'Dubai, AE', 4, 'Great fabric', 'Doesn''t wrinkle on long flights. Needed a belt as the waist runs slightly big.', TRUE, '2026-08-30T15:03:48.851Z'),
(49, 22, NULL, 'Kate O.', 'Auckland, NZ', 5, 'Bought five', 'The neck hasn''t stretched after months of washing. Worth the price over cheap tees.', TRUE, '2026-08-12T15:03:48.851Z'),
(50, 22, NULL, 'Ben A.', 'Berlin, DE', 5, 'Perfect weight', 'Not see-through, not stiff. The Sage is a great soft green.', TRUE, '2026-07-11T15:03:48.851Z'),
(51, 22, NULL, 'Rina D.', 'Jakarta, ID', 4, 'Good, boxy fit', 'Very boxy through the body. I sized down and love it.', TRUE, '2026-05-30T15:03:48.851Z'),
(52, 23, NULL, 'Vivian L.', 'Hong Kong, HK', 5, 'Stays put', 'Danced for four hours without once pulling it up. That never happens with a strapless.', TRUE, '2026-08-15T15:03:48.851Z'),
(53, 23, NULL, 'Camille R.', 'Montreal, CA', 5, 'Sculptural', 'Looks like couture from the front and the back. Very flattering.', TRUE, '2026-06-17T15:03:48.851Z'),
(54, 24, NULL, 'Hiro S.', 'Okayama, JP', 5, 'The real thing', 'Proper shuttle-loom denim. Heavy, slubby and it''s already starting to fade at the elbows.', TRUE, '2026-09-03T15:03:48.851Z'),
(55, 24, NULL, 'Maya J.', 'Berlin, DE', 4, 'Size up', 'Very boxy. I sized up for layering and it''s perfect over the Cloudsoft crew.', TRUE, '2026-06-29T15:03:48.851Z'),
(56, 1, 1, 'Amelie Laurent', 'Paris, FR', 5, 'Still wearing it a year on', 'Third order from Nova and the quality has never slipped. Delivery to Paris took three days.', TRUE, '2026-08-10T18:31:32.109Z'),
(58, 19, 1, 'Amelie Laurent', '', 3, 'worth for rent', 'zczxczxzzzzzzzzzzzzzz', TRUE, '2026-09-09T18:54:44.646Z')
